import React, { useRef } from 'react';
import style from './style.scss';

import fileIcon from '../../images/uploadfileicon.svg';
import deleteIcon from '../../images/delete-file.svg';
import loaderIcon from '../../images/fileupload-loader.svg';
import { ClassNames } from '../../helper';


export default function ConfigureFileInput({
	label,
	name,
	onChange,
	required,
	loading = false,
	handleDelete,
	error,
	value = '',
	placeholder = '',
	accept = ''
}) {
	const [currentValue, setCurrentValue] = React.useState('');
	const [dropText, setDropText] = React.useState(
		wp.i18n.__('Drag and drop file here', 'offload-media-cloud-storage')
	);
	const fileInput = useRef(null);
	const dragDropRef = useRef(null);

	const handleChange = (e) => {
		onChange(e);
		setCurrentValue(e.target.value);
	};

	React.useEffect(() => {
		if (currentValue !== '') {
			setCurrentValue('');
		}
	}, [currentValue]);

	const dragEnter = (e) => {
		e.preventDefault();
		setDropText(wp.i18n.__('Drop', 'offload-media-cloud-storage'));
	};
	const dragLeave = (e) => {
		e.preventDefault();
		setDropText(wp.i18n.__('Drag and drop files here', 'offload-media-cloud-storage'));
	};
	const fileDrop = (e) => {
		e.preventDefault();
		setDropText(wp.i18n.__('Drag and drop files here', 'offload-media-cloud-storage'));
		if (e?.dataTransfer?.files?.[0]) {
			onChange(e, true, name);
		}
	};

	return (
		<div className={style.inputBox}>
			{label && (
				<div className={style.label} htmlFor={name}>
					{label}
				</div>
			)}

			<div className={style.fileOuter}>
				<input
					type="file"
					name={name}
					id={name}
					placeholder={placeholder}
					onChange={handleChange}
					value={currentValue}
					required={required}
					ref={fileInput}
					accept={accept}
				/>
				<div
					ref={dragDropRef}
					onDragOver={dragEnter}
					onDragEnter={dragEnter}
					onDragLeave={dragLeave}
					onDrop={fileDrop}
					onClick={() => fileInput.current.click()}
					onKeyUp={() => fileInput.current.click()}
					role="button"
					tabIndex={0}
					className={ClassNames([
						style.dropOuter,
						error && style.error
					])}
				>
					<img src={fileIcon} alt="" />
					<div className={style.inner}>
						<h5>{wp.i18n.__('Upload a file', 'offload-media-cloud-storage')}</h5>
						<p>{dropText}</p>
					</div>
					{loading && (
						<div className={style.loader}>
							<img src={loaderIcon} alt="" />
						</div>
					)}
				</div>
				{value?.path && (
					<div className={style.fileList}>
						<div className={style.item}>
							<div className={style.title}>{value?.filename}</div>
							<div
								className={style.delete}
								onClick={() =>
									handleDelete({
										key: name,
										required
									})
								}
								onKeyDown={() =>
									handleDelete({
										key: name,
										required
									})
								}
								role="button"
								tabIndex={0}
							>
								<img src={deleteIcon} alt="" />
							</div>
						</div>
					</div>
				)}
			</div>
		</div>
	);
}
