import React from 'react';
import { ClassNames } from '../../helper';
import style from './style.scss';


export default function ConfigureVerifyFooter({
	onNext,
	onPrev,
	connection,
	saveConfig
}) {
	return (
		!connection.status && (
			<div className={style.footer}>
				<div className={style.btnSec}>
					{connection.error ? (
						<button
							onClick={onPrev}
							type="button"
							className={style.btnBack}
						>
							{wp.i18n.__('Back', 'offload-media-cloud-storage')}
						</button>
					) : (
						<>
							<button
								onClick={onNext}
								type="button"
								disabled={saveConfig.status}
								className={ClassNames([
									style.btnNext,
									saveConfig.status ? style.loading : ''
								])}
							>
								{wp.i18n.__(
									'Save Configuration',
									'offload-media-cloud-storage'
								)}
							</button>
							{saveConfig.error && (
								<span className={style.errorMsg}>
									{saveConfig.message}
								</span>
							)}
						</>
					)}
				</div>
			</div>
		)
	);
}
