import React from 'react';
import style from './style.scss';


export default function Welcome() {
	return (
		<div className={style.welcome}>
			<div className={style.left}>
				<h3>{wp.i18n.__('Hey there,', 'offload-media-cloud-storage')}</h3>
				<p>
					{wp.i18n.__(
						'Welcome to Offload Media Dashboard',
						'offload-media-cloud-storage'
					)}
				</p>
			</div>
			<div className={style.right}>
				<a
					href="http://support.acowebs.com"
					target="_blank"
					rel="noreferrer"
				>
					{wp.i18n.__('Support', 'offload-media-cloud-storage')}
				</a>
			</div>
		</div>
	);
}
