import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import style from './style.scss';

import { removeAlert, addAlert } from '../../redux/slices/alertsSlice';
import { ClassNames } from '../../helper';
import MultiStepNavigator from '../../components/MultiStepNavigator';
import ConfigureTextInput from '../../components/ConfigureTextInput';
import ConfigureToggleInput from '../../components/ConfigureToggleInput';
import ConfigureSelectInput from '../../components/ConfigureSelectInput';
import ConfigureFileInput from '../../components/ConfigureFileInput';
import uploadFile from '../../utils/uploadFile';
import Alert from '../../components/Alert';


function ConfigureServiceSettings(props) {
	const {
		setConfiguration,
		configuration,
		setErrors,
		fieldErrors,
	} = props;
	const configure = useSelector((state) => state.tempService);
	const alerts =  useSelector((state) => state.alerts);
	const dispatch = useDispatch();
	const { service } = configure;
	const [currentService, setCurrentService] = React.useState(service);
	const [currentAlerts, setCurrentAlerts] = React.useState([]);
	const [loadingArray, setLoadingArray] = React.useState([]);

	React.useEffect(() => {
		setCurrentAlerts(alerts);
	}, [alerts]);

	useEffect(() => {
		setCurrentService(service);
	}, [service]);

	const closeAlert = (e) => {
		dispatch(removeAlert(e));
	};

	useEffect(() => {
		setCurrentService((item) => {
			return {
				...item,
				fields: item.fields?.map((val) => {
					return {
						...val,
						error: !(fieldErrors?.errors?.indexOf(val?.name) === -1)
					};
				})
			};
		});
	}, [fieldErrors]);

	const validateField = (target) => {
		let sectionError = '';
		const value = target?.value;

		// If its a file
		if (target.required && typeof value === 'object' && !value?.path) {
			sectionError = target.name;
		} else if (target.required && !value) {
			sectionError = target.name;
		} else if (target.pattern && !RegExp(target.pattern, 'g').test(value)) {
			sectionError = target.name;
		} else if (target.max && value.length > target.max) {
			sectionError = target.name;
		}

		setErrors((prevErrors) => {
			const newErrors = [...prevErrors?.errors];

			if (sectionError) {
				if (newErrors.indexOf(target.name) === -1) {
					newErrors.push(sectionError);
				}
			} else if (newErrors.indexOf(target.name) !== -1) {
				newErrors.splice(newErrors.indexOf(target.name), 1);
			}

			return {
				errors: newErrors,
				isValid: newErrors.length === 0
			};
		});
	};

	const handleTextInput = (event) => {
		setConfiguration({
			...configuration,
			[event.target.name]: event.target.value
		});

		validateField(event.target);
	};
	const handleToggleInput = (event) => {
		setConfiguration({
			...configuration,
			[event.target.name]: event.target.checked
		});
	};

	const handleSelectInput = (event, field) => {
		setConfiguration({
			...configuration,
			[field.name]: event.value
		});

		validateField({ name: field.name, value: event.value });
	};

	const uploadFileToServer = (file, name = '') => {
		setLoadingArray([...loadingArray, name]);
		uploadFile(file)
			.then((response) => {
				setLoadingArray((prevValue) => {
					const newArray = [...prevValue];
					const index = newArray.indexOf(name);
					if (index !== -1) {
						newArray.splice(index, 1);
					}
					return newArray;
				});
				setConfiguration({
					...configuration,
					[name]: {
						filename: response?.file_name || '',
						path: response?.file_path || ''
					}
				});
			})
			.catch((error) => {
				setLoadingArray((prevValue) => {
					const newArray = [...prevValue];
					const index = newArray.indexOf(name);
					if (index !== -1) {
						newArray.splice(index, 1);
					}
					return newArray;
				});
				const orderId = `${Math.floor(
					Math.random() * 10000
				)}-${+new Date()}`;
				dispatch(addAlert({
					type: 'error',
					message: error,
					order: orderId
				}));
				setConfiguration({
					...configuration,
					[name]: {
						filename: error || ''
					}
				});
				setErrors((prevErrors) => {
					const newErrors = [...prevErrors?.errors];

					if (newErrors.indexOf(name) === -1) {
						newErrors.push(name);
					}

					return {
						errors: newErrors,
						isValid: newErrors.length === 0
					};
				});
			});
	};

	const handleFileChange = ({ target, dataTransfer }, dropUpload = false, name = false) => {
		if(dropUpload) {
			const file = dataTransfer?.files?.[0];
			
			setErrors((prevErrors) => {
				const newErrors = [...prevErrors?.errors];
	
				if (newErrors.indexOf(name) !== -1) {
					newErrors.splice(newErrors.indexOf(name), 1);
				}
	
				return {
					errors: newErrors,
					isValid: newErrors.length === 0
				};
			});
			setConfiguration({
				...configuration,
				[name]: {
					filename: file?.name || ''
				}
			});
			;
			uploadFileToServer(file, name);
		} else {
			setErrors((prevErrors) => {
				const newErrors = [...prevErrors?.errors];
	
				if (newErrors.indexOf(target.name) !== -1) {
					newErrors.splice(newErrors.indexOf(target.name), 1);
				}
	
				return {
					errors: newErrors,
					isValid: newErrors.length === 0
				};
			});
			setConfiguration({
				...configuration,
				[target.name]: {
					filename: target?.files[0]?.name || ''
				}
			});

			if (target?.files[0]) {
				uploadFileToServer(target?.files[0], target.name);
			}
		}
	};

	const handleDelete = ({ key, ...target }) => {
		setConfiguration({
			...configuration,
			[key]: {
				filename: '',
				path: ''
			}
		});

		validateField({ name: key, ...target });
	};

	return (
		<div className={ClassNames([style.content, style.serviceSettings])}>
			{service.title && (
				<>
					<MultiStepNavigator
						currentStep={2}
						serviceName={service.title}
					/>
					<div className={style.inner}>
						<h2>
							{` ${service.title} `}
							{wp.i18n.__('Settings', 'offload-media-cloud-storage')}
						</h2>
						<p>{service.settingsDescription}</p>
						{currentService?.fields?.map((field) => {
							switch (field.type) {
								case 'text':
									return (
										<ConfigureTextInput
											key={field?.name}
											label={field?.label}
											placeholder={field?.placeholder}
											name={field?.name}
											type={field?.type}
											pattern={field?.regex}
											max={field?.maxLength}
											min={field?.minLength}
											value={
												configuration?.[field?.name] ||
												''
											}
											required={field?.required}
											onChange={(e) =>
												handleTextInput(e, field?.name)
											}
											error={field?.error}
										/>
									);
								case 'number':
									return (
										<ConfigureTextInput
											key={field.name}
											label={field.label}
											placeholder={field.placeholder}
											name={field.name}
											type={field.type}
											value={
												configuration?.[field.name] ||
												''
											}
											required={field?.required}
											onChange={(e) =>
												handleTextInput(e, field.name)
											}
											error={field.error}
										/>
									);
								case 'toggle':
									return (
										<ConfigureToggleInput
											key={field.name}
											label={field.label}
											name={field.name}
											tooltip={field?.description}
											value={
												configuration?.[field.name] ||
												false
											}
											required={field.required}
											onChange={handleToggleInput}
										/>
									);
								case 'select':
									return (
										<ConfigureSelectInput
											key={field.name}
											label={field.label}
											name={field.name}
											value={
												configuration?.[field.name]
													? field.values.filter(
															(obj) => {
																return (
																	obj.value ===
																	configuration?.[
																		field
																			.name
																	]
																);
															}
													  )
													: false
											}
											required={field.required}
											options={field.values}
											onChange={handleSelectInput}
											error={field.error}
										/>
									);
								case 'file':
									return (
										<ConfigureFileInput
											key={field.name}
											label={field.label}
											name={field.name}
											loading={
												loadingArray.indexOf(
													field.name
												) !== -1
											}
											value={
												configuration?.[field.name] ||
												{}
											}
											accept={field.accept}
											handleDelete={handleDelete}
											required={field.required}
											options={field.values}
											onChange={handleFileChange}
											error={field.error}
										/>
									);
								default:
									return null;
							}
						})}
					</div>
					{currentAlerts?.length ? (
						<div className={style.alertContainer}>
							{currentAlerts?.map((alrt) => {
								return (
									<Alert
										key={alrt.order}
										type={alrt.type}
										message={alrt.message}
										onClose={(e) => closeAlert(e)}
										index={alrt.order}
									/>
								);
							})}
						</div>
					) : (
						''
					)}
				</>
			)}
		</div>
	);
}
export default ConfigureServiceSettings;
