import React from 'react';
import style from './style.scss';

function LicenseNavigation({ sections, contRef, active, setActive }) {
	const handleFocus = (ref, key) => {
		contRef.current.scrollTo({
			top: ref.current.offsetTop,
			// behavior: 'smooth'
		});
		setActive(key);
	};
	return (
		<ul className={style.container}>
			{sections?.map((section) => (
				<li
					key={section.key}
					aria-hidden
					onClick={() => handleFocus(section.ref, section.key)}
					className={active === section.key ? style.active : ''}
				>
					{section.title}
				</li>
			))}
		</ul>
	);
}
export default LicenseNavigation;
