import React from 'react';
import { ClassNames } from '../../helper';
import style from './style.scss';


export default function MultiStepNavigator({ currentStep, serviceName = '' }) {
	const steps = [
		{
			step: 1,
			text: wp.i18n.__('Getting Started', 'offload-media-cloud-storage')
		},
		{
			step: 2,
			text: wp.i18n.__(`${serviceName} Configure`, 'offload-media-cloud-storage')
		},
		{
			step: 3,
			text: wp.i18n.__('Verify', 'offload-media-cloud-storage')
		},
		{
			step: 4,
			text: wp.i18n.__('Complete', 'offload-media-cloud-storage')
		}
	];

	return (
		<div className={style.MultiStepNavigator}>
			{steps.map((step) => {
				return (
					<div
						key={step.step}
						className={ClassNames([
							style.step,
							step.step === currentStep ? style.active : '',
							step.step < currentStep ? style.completed : ''
						])}
					>
						<div className={style.number}>{step.step}</div>
						<div className={style.text}>{step.text}</div>
						<span />
					</div>
				);
			})}
		</div>
	);
}
