import { createSlice } from "@reduxjs/toolkit";

const initialState = []

const alertsSlice = createSlice({
    name: 'alerts',
    initialState,
    reducers : {
        addAlert: (state, action) => {
            state.push(action.payload); // Adds a new alert
        },
        removeAlert: (state, action) => {
            return state.filter((item) => item.order !== action.payload); // Removes an alert by `order`
        },
        updateAlerts: (state, action) => {
            return action.payload; // Replaces the state with the new alerts
        },
    }
})

// Export actions
export const { addAlert, removeAlert, updateAlerts } = alertsSlice.actions;

// Export reducer
export default alertsSlice.reducer;