import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  service: {},
  credentials: {},
};

const tempServiceSlice = createSlice({
  name: 'tempService',
  initialState,
  reducers: {
    updateTempCredentials: (state, action) => {
      state.credentials = action.payload; // Updates the `credentials` property
    },
    updateTempService: (state, action) => {
      state.service = action.payload; // Updates the `service` property
    },
    updateTempServiceProp: (state, action) => {
      return action.payload; // Replaces the entire state
    },
  },
});

// Export actions
export const { 
    updateTempCredentials, 
    updateTempService, 
    updateTempServiceProp 
} = tempServiceSlice.actions;

// Export reducer
export default tempServiceSlice.reducer;
