import React from 'react';
import SettingsPage from '../../pages/Settings/SettingsPage';
import style from './style.scss';

export default function SettingsContent({
	sections,
	fields,
	contRef,
	values,
	errorElements,
	handleChangeValues,
	handleScroll
}) {
	return (
		<div className={style.contentSec}>
			<div className={style.inner} ref={contRef} onScroll={handleScroll}>
				{sections?.map((sec) => {
					return (
						<SettingsPage
							key={sec.key}
							section={sec}
							fields={fields?.[sec.key]}
							values={values}
							errorElements={errorElements}
							handleChangeValues={(key, value)=>handleChangeValues(key, value)}
						/>
					);
				})}
			</div>
		</div>
	);
}
