import React from 'react';
import preloader from '../images/preloader.svg';
import style from '../backend.scss';


export default function Loader() {
	return (
		<div className={style.pageLoading}>
			<img
				src={preloader}
				alt={wp.i18n.__('Offload Media - Cloud Storage', 'offload-media-cloud-storage')}
			/>
			<p>{wp.i18n.__('Loading please wait...', 'offload-media-cloud-storage')}</p>
		</div>
	);
}
