import React from 'react';
import { NavLink, withRouter } from 'react-router-dom';
import style from './style.scss';
import arrow from '../../images/icon-arrow.svg';

import { ClassNames } from '../../helper';

function CardSmall({
	title,
	description,
	icon,
	color,
	link,
	disabled,
	external,
	service = false
}) {
	return external ? (
		<a href={link} target="_blank" rel="noreferrer" className={style.link}>
			<div className={style.card}>
				<div className={style.imgSec}>
					<div
						className={style.imgInner}
						style={{ backgroundColor: color }}
					>
						<img src={icon} alt={title} />
					</div>
				</div>
				<div className={style.content}>
					<h4>{title}</h4>
					<p>{description}</p>
				</div>
				<div className={style.arrowSec}>
					<img src={arrow} alt={title} />
				</div>
			</div>
		</a>
	) : (
		<NavLink
			exact
			className={style.link}
			to={link}
			onClick={(e) => (disabled ? e.preventDefault() : '')}
		>
			<div
				className={ClassNames([style.card, disabled && style.disabled])}
			>
				{service?.active && (
					<div className={style.serviceSec}>
						{`${service.name} / ${service.bucket} connected`}
					</div>
				)}
				<div className={style.imgSec}>
					<div
						className={style.imgInner}
						style={{ backgroundColor: color }}
					>
						<img src={icon} alt={title} />
					</div>
				</div>
				<div className={style.content}>
					<h4>{title}</h4>
					<p>{description}</p>
				</div>
				<div className={style.arrowSec}>
					<img src={arrow} alt={title} />
				</div>
			</div>
		</NavLink>
	);
}

export default withRouter(CardSmall);
