import React from 'react';
import LicenseSettings from '../../pages/Settings/LicenseSettings';
import style from './style.scss';

export default function LicenseContent({ sections, contRef, handleScroll }) {
	return (
		<div className={style.contentSec}>
			<div className={style.inner} ref={contRef} onScroll={handleScroll}>
				<LicenseSettings
					reference={
						sections?.find(({ key }) => key === 'license_settings')
							.ref
					}
					id="license_settings"
				/>
			</div>
		</div>
	);
}
