import React from 'react';
import style from './style.scss';


export default function CardLarge({ title, count, total, link, icon, color }) {
	return (
		<div className={style.card}>
			{icon && (
				<div className={style.imgSec}>
					<div
						className={style.imgInner}
						style={{ backgroundColor: color }}
					>
						<img src={icon} alt={title} />
					</div>
				</div>
			)}
			{title && (
				<>
					<div className={style.content}>
						<h4>{title}</h4>
						<div className={style.count}>
							{count}{' '}
							{total !== false ? <span>/{total}</span> : ''}
						</div>
					</div>
					{link && (
						<a
							className={style.purchase}
							href={link}
							target="_blank"
							rel="noreferrer"
						>
							{wp.i18n.__('Purchase Media', 'offload-media-cloud-storage')}
						</a>
					)}
				</>
			)}
		</div>
	);
}
