/* eslint-disable jsx-a11y/label-has-associated-control */
import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { ClassNames } from '../../helper';
import { Services, logos } from '../../utils/variables';
import { updateTempService } from '../../redux/slices/tempServiceSlice';

import style from './style.scss';

import helpIcon from '../../images/help.svg';
import activeIcon from '../../images/selected.svg';

function ConfigureChooseService(prop) {
	const [selected, setSelected] = React.useState(0);
	const tempPropService = useSelector((state) => state.tempService);
	const dispatch = useDispatch();

	React.useEffect(() => {
		if (Object.entries(tempPropService.service).length !== 0) {
			let index = false;
			Services.map((service, key) => {
				if (index === false) {
					index =
						tempPropService.service.slug === service.slug
							? key
							: false;
				}
				return null;
			});
			if (index !== false) {
				setSelected(index);
			}
		} else {
			setSelected(0);
			dispatch(updateTempService(Services[0]));
		}
	}, []);

	const handleServiceChange = (e) => {
		const index = parseInt(e.target.value, 10);
		setSelected(index);
		dispatch(updateTempService(Services[index]));
	};

	return (
		<div className={ClassNames([style.content, style.services])}>
			<h3>
				{wp.i18n.__(
					'Choose the Service Provider',
					'offload-media-cloud-storage'
				)}
			</h3>
			<div className={style.servicePool}>
				{Services.map((service, index) => {
					return (
						<label className={style.item} key={service.slug}>
							<input
								type="radio"
								name="choose_provider"
								value={index}
								onChange={handleServiceChange}
								checked={selected === index}
							/>
							<div className={style.serviceInner}>
								<img
									src={logos?.[service.slug]}
									alt={service.title}
									className={style.logo}
								/>
								<img
									src={activeIcon}
									alt=""
									className={style.activeIcon}
								/>
								<div className={style.tooltipSec}>
									<img
										src={helpIcon}
										alt=""
										className={style.helpIcon}
									/>
									<div className={style.ToolTipContent}>
										<h6>{service.title}</h6>
										<p>{service.tooltip}</p>
									</div>
								</div>
							</div>
						</label>
					);
				})}
			</div>
		</div>
	);
}

export default ConfigureChooseService;
