import React from 'react';
import ToggleInput from '../../components/ToggleInput';
import TextInput from '../../components/TextInput';

import style from './style.scss';

export default function SettingsPage({
	section,
	fields,
	values,
	errorElements,
	handleChangeValues
}) {
	return (
		<div
			ref={section?.ref}
			id={section?.key}
			className={style.settingsInner}
		>
			<h2>{section?.title}</h2>
			{fields?.map((field) => {
				if (field?.parent) {
					if (!values?.[field?.parent]) {
						return false;
					}
				}
				switch (field?.type) {
					case 'toggle':
						return (
							<ToggleInput
								key={field?.name}
								label={field?.label}
								name={field?.name}
								tooltip={field?.desc}
								warning={
									field?.warning ? field?.warning : false
								}
								checked={values?.[field?.name]}
								handleChangeValues={(key, value) =>
									handleChangeValues(key, value)
								}
							/>
						);
					case 'text':
						return (
							<TextInput
								key={field?.name}
								label={field?.label}
								name={field?.name}
								tooltip={field?.desc}
								required={field?.required}
								placeholder={field?.placeholder}
								value={values?.[field?.name]}
								className={
									errorElements.indexOf(field?.name) !== -1
										? 'InputError'
										: ''
								}
								handleChangeValues={(key, value) =>
									handleChangeValues(key, value)
								}
							/>
						);
					case 'number':
						return (
							<TextInput
								key={field?.name}
								label={field?.label}
								name={field?.name}
								tooltip={field?.desc}
								required={field?.required}
								placeholder={field?.placeholder}
								value={values?.[field?.name]}
								min={field?.minValue}
								pattern={field?.regex}
								max={field?.maxValue}
								lenMin={field?.minLength}
								lenMax={field?.maxLength}
								type={field?.type}
								className={
									errorElements.indexOf(field?.name) !== -1
										? 'InputError'
										: ''
								}
								handleChangeValues={(key, value) =>
									handleChangeValues(key, value)
								}
							/>
						);
					case 'tel':
						return (
							<TextInput
								key={field?.name}
								label={field?.label}
								name={field?.name}
								tooltip={field?.desc}
								required={field?.required}
								placeholder={field?.placeholder}
								value={values?.[field?.name]}
								min={field?.minValue}
								pattern={field?.regex}
								max={field?.maxValue}
								type={field?.type}
								className={
									errorElements.indexOf(field?.name) !== -1
										? 'InputError'
										: ''
								}
								handleChangeValues={(key, value) =>
									handleChangeValues(key, value)
								}
							/>
						);
					default:
						return null;
				}
			})}
		</div>
	);
}
