import React, { useRef } from 'react';
import style from './style.scss';

import LicenseHeader from '../components/LicenseHeader';
import LicenseNavigation from '../components/LicenseNavigation';
import LicenseContent from '../components/LicenseContent';
import LicenseFooter from '../components/LicenseFooter';
import { setCurrentMenu } from '../helper';

export default function License() {
	const licenseRef = useRef(null);
	const containerRef = useRef(null);

	const [active, setActive] = React.useState('license_settings');

	React.useEffect(() => {
		setCurrentMenu('license');
	}, []);

	const sections = [
		{
			title: wp.i18n.__('License', 'offload-media-cloud-storage'),
			ref: licenseRef,
			key: 'license_settings'
		}
	];

	const handleScroll = (e) => {
		setActive((prevKey) => {
			const key = sections?.find(
				({ ref }) =>
					ref?.current?.offsetTop +
						ref?.current?.offsetHeight * 0.8 >=
					e.target.scrollTop
			)?.key;
			return key || prevKey;
		});
	};

	return (
		<>
			<LicenseHeader />
			<div className={style.SettingsInner}>
				<div className={style.left}>
					<LicenseNavigation
						sections={sections}
						contRef={containerRef}
						active={active}
						setActive={setActive}
					/>
				</div>
				<div className={style.right}>
					<LicenseContent
						contRef={containerRef}
						sections={sections}
						handleScroll={handleScroll}
					/>
					<LicenseFooter />
				</div>
			</div>
		</>
	);
}
