import React from 'react';
import style from './style.scss';


export default function PremiumBanner() {
	return (
		<div className={style.banner}>
			<div className={style.content}>
				<h3>{wp.i18n.__('We are building something awesome!', 'offload-media-cloud-storage')}</h3>
				<h6>{wp.i18n.__('Premium version coming soon, get notified when we launch', 'offload-media-cloud-storage')}</h6>
			</div>
			<a
				href="https://acowebs.com"
				target="_blank"
				rel="noreferrer"
				className={style.learn_more}
			>
				{wp.i18n.__('Learn More', 'offload-media-cloud-storage')}
			</a>
		</div>
	);
}
