import React from 'react';
import { NavLink, withRouter } from 'react-router-dom';
import style from './style.scss';

import iconClose from '../../images/icon-close.svg';


function CloseConfiguration({ handlePopup }) {
	return (
		<div className={style.popupOuter}>
			<div className={style.inner}>
				<div className={style.content}>
					<h4>{wp.i18n.__('Close Setup Wizard', 'offload-media-cloud-storage')}</h4>
					<p>
						{wp.i18n.__(
							'Are you sure do you want to close the setup wizard ?',
							'offload-media-cloud-storage'
						)}
					</p>
					<button type="button" onClick={() => handlePopup(false)}>
						<img src={iconClose} alt="" />
					</button>
				</div>
				<div className={style.footer}>
					<NavLink exact className={style.cancel} to='/'>
						{wp.i18n.__('OK', 'offload-media-cloud-storage')}
					</NavLink>
					<button
						type="button"
						className={style.primaryBtn}
						onClick={() => handlePopup(false)}
					>
						{wp.i18n.__('Cancel', 'offload-media-cloud-storage')}
					</button>
					
				</div>
			</div>
		</div>
	);
}
export default withRouter(CloseConfiguration);
