import React from 'react';
import Select from 'react-select';
import { ClassNames } from '../../helper';
import style from './style.scss';

export default function ConfigureSelectInput({
	label,
	name,
	onChange,
	required,
	value = false,
	options = [],
	error= false
}) {
	return (
		<div className={style.inputBox}>
			{label && <label htmlFor={name}>{label}</label>}
			<Select
				name={name}
				id={name}
				// value={value || options?.[0]}
				// defaultValue={value || options?.[0]}
				value={value}
				defaultValue={value}
				onChange={onChange}
				required={required}
				options={options}
				className={ClassNames(["react-select-configure-container", error && style.error])}
				classNamePrefix="react-select-configure"
			/>
		</div>
	);
}
