import React from 'react';
import { useSelector } from 'react-redux';
import style from './style.scss';
import logo from '../../images/logo.svg';
import { acoofmGetBucketName } from '../../helper';

function Header(props) {
	const { version = '1.0.0' } = props;
	const configure = useSelector((state) => state.common?.configure);

	const [service, setService] = React.useState({
		active: false,
		service: '',
		bucket: ''
	});
	React.useEffect(() => {
		setService({
			active: !!Object.keys(configure?.service).length,
			name: Object.keys(configure?.service).length
				? configure?.service.title
				: '',
			bucket: Object.keys(configure?.service).length
				? acoofmGetBucketName(
						configure?.service,
						configure?.credentials
				  )
				: ''
		});
	}, [configure]);
	return (
		<div className={style.header}>
			<div className={style.left}>
				<img src={logo} alt="" />
			</div>
			<div className={style.right}>
				{service?.active && (
					<div
						className={style.active}
					>{`${service.name} / ${service.bucket}`}</div>
				)}
				<div className={style.version}>{version}</div>
				<a
					href="https://acowebs.com"
					className={style.btn}
					target="_blank"
					rel="noreferrer"
				>
					{wp.i18n.__(
						'CHECK PREMIUM OPTIONS',
						'offload-media-cloud-storage'
					)}
				</a>
			</div>
		</div>
	);
}

export default Header;
