import React, { useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import style from './style.scss';

import SettingsHeader from '../components/SettingsHeader';
import SettingsNavigation from '../components/SettingsNavigation';
import SettingsContent from '../components/SettingsContent';
import SettingsFooter from '../components/SettingsFooter';
import Alert from '../components/Alert';
import ConfirmReset from '../components/ConfirmReset';

import { fetchWP, setCurrentMenu } from '../helper';
import { settingsFields, settingsDefaultValues } from '../utils/fields';
import { removeAlert, addAlert } from '../redux/slices/alertsSlice';
import { updateSettings } from '../redux/slices/commonSlice';
import ConfirmEnable from '../components/ConfirmEnable';

function PluginSettings(props) {
	const configure = useSelector((state) => state.common.configure);
	const settings = useSelector((state) => state.common.settings);
	const alerts = useSelector((state) => state.alerts);
	const dispatch = useDispatch();

	const { service } = configure;
	const [currentSections, setCurrentSections] = React.useState([]);
	const [currentFields, setCurrentFields] = React.useState([]);
	const [currentAlerts, setCurrentAlerts] = React.useState([]);
	const [currentSettings, setCurrentSettings] = React.useState({});
	const [valid, setValid] = React.useState(true);
	const [errorFields, setErrorFields] = React.useState([]);
	const [loader, setLoader] = React.useState(false);
	const [confirm, setConfirm] = React.useState(false);
	const [warning, setWarning] = React.useState({
		status: false,
		key: '',
		value: '',
		message: ''
	});

	const basicRef = useRef(null);
	// const advancedRef = useRef(null);
	const containerRef = useRef(null);

	const [active, setActive] = React.useState('settings');

	React.useEffect(() => {
		setCurrentMenu('settings');
	}, []);

	const sections = [
		{
			service: 's3',
			sections: [
				{
					title: wp.i18n.__(
						'Settings',
						'offload-media-cloud-storage'
					),
					ref: basicRef,
					key: 'settings'
				}
			]
		},
		{
			service: 'google',
			sections: [
				{
					title: wp.i18n.__(
						'Settings',
						'offload-media-cloud-storage'
					),
					ref: basicRef,
					key: 'settings'
				}
			]
		},
		{
			service: 'ocean',
			sections: [
				{
					title: wp.i18n.__(
						'Settings',
						'offload-media-cloud-storage'
					),
					ref: basicRef,
					key: 'settings'
				}
			]
		},
		{
			service: 'r2',
			sections: [
				{
					title: wp.i18n.__(
						'Settings',
						'offload-media-cloud-storage'
					),
					ref: basicRef,
					key: 'settings'
				}
			]
		}
	];

	React.useEffect(() => {
		let errorInField = false;
		currentSections?.map((sec) => {
			currentFields?.[sec?.key]?.map((field) => {
				if (field?.required) {
					if (!currentSettings?.[field?.name]) {
						if (!currentSettings?.[field?.parent]) {
							setErrorFields((prevValue) => {
								const newVal = [...prevValue];
								const index = newVal.indexOf(field?.name);
								if (index !== -1) {
									newVal.splice(index, 1);
								}
								return newVal;
							});
						} else {
							setErrorFields((prevValue) => {
								const newVal = [...prevValue];
								if (newVal.indexOf(field?.name) === -1) {
									newVal.push(field?.name);
								}
								return newVal;
							});
							errorInField = true;
						}
					} else {
						setErrorFields((prevValue) => {
							const newVal = [...prevValue];
							const index = newVal.indexOf(field?.name);
							if (index !== -1) {
								newVal.splice(index, 1);
							}
							return newVal;
						});
					}
				}
				return null;
			});
			return null;
		});
		setValid(!errorInField);
	}, [currentSettings]);

	React.useEffect(() => {
		setCurrentAlerts(alerts);
	}, [alerts]);

	React.useEffect(() => {
		sections.map((serviceSec) => {
			if (serviceSec?.service === service?.slug) {
				setCurrentSections(serviceSec?.sections);
				setCurrentFields(settingsFields?.[service?.slug]);
			}
			return null;
		});
		setCurrentSettings(settings);
	}, [service]);

	React.useEffect(() => {
		setCurrentSettings(settings);
	}, [settings]);

	const handleScroll = (e) => {
		setActive((prevKey) => {
			const key = currentSections?.find(
				({ ref }) =>
					ref?.current?.offsetTop +
						ref?.current?.offsetHeight * 0.8 >=
					e.target.scrollTop
			)?.key;
			return key || prevKey;
		});
	};

	const handleChangeValues = (key, value, noCheck = false) => {
		if (!noCheck) {
			let field = false;
			if (currentFields) {
				field = currentFields?.settings?.find(
					(fld) => fld?.name === key
				);
			}
			if (field?.warning?.enable && value) {
				setWarning({
					status: true,
					key,
					value,
					message: field?.warning?.message
				});
			} else {
				setCurrentSettings({
					...currentSettings,
					[key]: value
				});
			}
		} else {
			setCurrentSettings({
				...currentSettings,
				[key]: value
			});
		}
	};

	const confirmWarning = (key, value) => {
		setWarning({
			status: false,
			key: '',
			value: '',
			message: ''
		});
		handleChangeValues(key, value, true);
	};

	const cancelWarning = () => {
		setWarning({
			status: false,
			key: '',
			value: '',
			message: ''
		});
	};

	const handleSave = () => {
		setLoader(true);
		fetchWP
			.post('settingsSave/', {
				settings: currentSettings
			})
			.then((response) => {
				dispatch(updateSettings(currentSettings));
				const orderId = `${Math.floor(
					Math.random() * 10000
				)}-${+new Date()}`;
				dispatch(addAlert({
					type: 'success',
					message: response,
					order: orderId
				}));
				setLoader(false);
			})
			.catch((error) => {
				const orderId = `${Math.floor(
					Math.random() * 10000
				)}-${+new Date()}`;
				dispatch(addAlert({
					type: 'error',
					message: error,
					order: orderId
				}));
				setLoader(false);
			});
	};

	const handleReset = () => {
		setConfirm(true);
	};

	const cancelReset = () => {
		setLoader(false);
		setConfirm(false);
	};

	const closeAlert = (e) => {
		dispatch(removeAlert(e));
	};

	const proceedReset = () => {
		setConfirm(false);
		setLoader(true);
		fetchWP
			.post('settingsReset/', {
				settings: settingsDefaultValues?.[service?.slug]
			})
			.then((response) => {
				setCurrentSettings(settingsDefaultValues?.[service?.slug]);
				dispatch(updateSettings(settingsDefaultValues?.[service?.slug]));
				const orderId = `${Math.floor(
					Math.random() * 10000
				)}-${+new Date()}`;
				dispatch(addAlert({
					type: 'success',
					message: response,
					order: orderId
				}));
				setLoader(false);
			})
			.catch((error) => {
				const orderId = `${Math.floor(
					Math.random() * 10000
				)}-${+new Date()}`;
				dispatch(addAlert({
					type: 'error',
					message: error,
					order: orderId
				}));
				setLoader(false);
			});
	};

	return (
		<>
			{warning?.status && (
				<ConfirmEnable
					onCancel={cancelWarning}
					warning={warning}
					onSubmit={confirmWarning}
				/>
			)}
			{confirm && (
				<ConfirmReset onCancel={cancelReset} onSubmit={proceedReset} />
			)}
			<>
				<SettingsHeader />
				<div className={style.SettingsInner}>
					<div className={style.left}>
						<SettingsNavigation
							sections={currentSections}
							contRef={containerRef}
							active={active}
							setActive={setActive}
						/>
					</div>
					<div className={style.right}>
						<SettingsContent
							contRef={containerRef}
							sections={currentSections}
							fields={currentFields}
							values={currentSettings}
							errorElements={errorFields}
							handleChangeValues={(key, value) =>
								handleChangeValues(key, value)
							}
							handleScroll={handleScroll}
						/>
						<SettingsFooter
							save={handleSave}
							reset={handleReset}
							disabled={!valid}
							loader={loader}
						/>
					</div>
					{currentAlerts?.length ? (
						<div className={style.alertContainer}>
							{currentAlerts?.map((alrt) => {
								return (
									<Alert
										key={alrt.order}
										type={alrt.type}
										message={alrt.message}
										onClose={(e) => closeAlert(e)}
										index={alrt.order}
									/>
								);
							})}
						</div>
					) : (
						''
					)}
				</div>
			</>
		</>
	);
}

export default PluginSettings;
