/* eslint-disable react/no-danger */
import React from 'react';
import { useSelector } from 'react-redux';
import MultiStepNavigator from '../../components/MultiStepNavigator';
import { ClassNames } from '../../helper';

import style from './style.scss';


function ConfigureChooseWelcome(props) {
	const configure = useSelector((state) => state.tempService);
	const { service } = configure;
	return (
		<div className={ClassNames([style.content, style.serviceWelcome])}>
			{service.title && (
				<>
					<MultiStepNavigator
						currentStep={1}
						serviceName={service.title}
					/>
					<h1>
						{wp.i18n.__('Get Started with', 'offload-media-cloud-storage')}
						{` ${service.title}`}
					</h1>
					<div
						className={style.description}
						dangerouslySetInnerHTML={{ __html: service.content }}
					/>
					<div className={style.buttonSec}>
						{service?.demo && (
							<a
								href={service.demo}
								target="_blank"
								rel="noreferrer"
								className={style.demo}
							>
								{wp.i18n.__('Watch Demo', 'offload-media-cloud-storage')}
							</a>
						)}
						{service?.documentation && (
							<a
								href={service.documentation}
								target="_blank"
								rel="noreferrer"
								className={style.doc}
							>
								{wp.i18n.__(
									'View Documentation',
									'offload-media-cloud-storage'
								)}
							</a>
						)}
					</div>
				</>
			)}
		</div>
	);
}

export default ConfigureChooseWelcome;
