import React from 'react';
import { useSelector } from 'react-redux';
import style from './style.scss';

import { ClassNames } from '../../helper';
import MultiStepNavigator from '../../components/MultiStepNavigator';

import connSuccess from '../../images/connection-success.svg';
import connFailed from '../../images/connection-failed.svg';


function ConfigureServiceComplete(props) {
	const configure = useSelector((state) => state.tempService);
	const connection = useSelector((state) => state.connection);
	const { service } = configure;

	return (
		<div className={ClassNames([style.content, style.serviceComplete])}>
			{service.title && (
				<>
					<MultiStepNavigator
						currentStep={4}
						serviceName={service.title}
					/>
					<div className={style.inner}>
						{connection.error ? (
							<>
								<div className={style.imgSec}>
									<div
										className={ClassNames([
											style.imgInner,
											style.error
										])}
									>
										<img
											src={connFailed}
											alt={wp.i18n.__(
												'Offload Media - Cloud Storage',
												'offload-media-cloud-storage'
											)}
										/>
									</div>
								</div>
								<h2>
									{wp.i18n.__(
										'Connection failed',
										'offload-media-cloud-storage'
									)}
								</h2>
								<p>{connection.message}</p>
							</>
						) : (
							<>
								<div className={style.imgSec}>
									<div
										className={ClassNames([
											style.imgInner,
											style.success
										])}
									>
										<img
											src={connSuccess}
											alt={wp.i18n.__(
												'Offload Media - Cloud Storage',
												'offload-media-cloud-storage'
											)}
										/>
									</div>
								</div>
								<h2>
									{wp.i18n.__('Success!', 'offload-media-cloud-storage')}
								</h2>
								<p>{connection.message}</p>
							</>
						)}
					</div>
				</>
			)}
		</div>
	);
}

export default ConfigureServiceComplete;
