import { createSlice } from '@reduxjs/toolkit';

export const commonState = {
	loader: true,
	dashboard: {},
	configure: {
		service: {},
		credentials: {},
	},
	settings: {},
};

const commonSlice = createSlice({
	name: 'common',
	initialState: commonState,
	reducers: {
		updateCommonSettings(state, action) {
			return action.payload; // Completely replace the state
		},
		updateLoader(state, action) {
			state.loader = action.payload; // Update the loader property
		},
		updateService(state, action) {
			state.configure.service = action.payload; // Update the service property inside configure
		},
		updateCredentials(state, action) {
			state.configure.credentials = action.payload; // Update the credentials property inside configure
		},
		updateSettings(state, action) {
			state.settings = action.payload; // Update the settings property
		},
	},
});

export const {
	updateCommonSettings,
	updateLoader,
	updateService,
	updateCredentials,
	updateSettings,
} = commonSlice.actions;

export default commonSlice.reducer;
