import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useHistory } from 'react-router';

import {
	updateCredentials,
	updateService,
	updateSettings
} from '../redux/slices/commonSlice';
import { setConnection } from '../redux/slices/connectionSlice';
import {
	updateTempCredentials,
	updateTempService,
	updateTempServiceProp
} from '../redux/slices/tempServiceSlice';

import ConfigureHeader from '../components/ConfigureHeader';
import ConfigureChooseService from './Configure/ConfigureChooseService';
import ConfigureWelcome from './Configure/ConfigureWelcome';
import ConfigureServiceWelcome from './Configure/ConfigureServiceWelcome';
import ConfigureServiceSettings from './Configure/ConfigureServiceSettings';
import ConfigureServiceVerify from './Configure/ConfigureServiceVerify';

import style from './style.scss';

import CloseConfiguration from '../components/CloseConfiguration';
import ConfigureFooter from '../components/ConfigureFooter';
import ConfigureVerifyFooter from '../components/ConfigureVerifyFooter';
import ConfigureServiceComplete from './Configure/ConfigureServiceComplete';

import { settingsDefaultValues } from '../utils/fields';
import { logos } from '../utils/variables';

import { fetchWP, setCurrentMenu } from '../helper';

function Configure(props) {
	const configure = useSelector((state) => state.common.configure);
	const connectionProp = useSelector((state) => state.connection);
	const tempConfigure = useSelector((state) => state.tempService);
	const dispatch = useDispatch();

	const history = useHistory();
	const { service, credentials: defaultCredentials } = configure;
	const { service: tempService } = tempConfigure;
	const [currentPage, setCurrentPage] = React.useState(0);
	const [credentials, setCredentials] = React.useState(defaultCredentials);
	const [closePopup, setClosePopup] = React.useState(false);
	const [errors, setErrors] = React.useState({ errors: [], isValid: true });

	const [valid, setValid] = React.useState(true);
	const [saveConfig, setSaveConfig] = React.useState({
		status: false,
		error: false,
		message: ''
	});
	const [connection, updateConnection] = React.useState({
		status: false,
		error: false,
		message: ''
	});

	React.useEffect(() => {
		setCurrentMenu('configure');
		dispatch(updateTempServiceProp({
			service,
			credentials
		}));
	}, []);

	const isValid = (data, fields) => {
		const sectionErrors = [];
		fields?.forEach((val) => {
			const value = data[val.name];
			if (val.required) {
				// If its a file
				if (typeof value === 'object') {
					if (!value?.path) {
						sectionErrors.push(val.name);
					}
				} else if (!value) {
					sectionErrors.push(val.name);
				}
			} else if (val.regex && !RegExp(val.regex, 'g').test(value)) {
				sectionErrors.push(val.name);
			} else if (val.maxLength && value.length > val.maxLength) {
				sectionErrors.push(val.name);
			}
		});
		setErrors({
			errors: sectionErrors,
			isValid: sectionErrors.length === 0
		});
		return { errors: sectionErrors, isValid: sectionErrors.length === 0 };
	};

	React.useEffect(() => {
		updateConnection(connectionProp);
	}, [connectionProp]);

	React.useEffect(() => {
		if (Object.keys(tempService).length) {
			setCurrentPage(1);
		}
		setCredentials(() => {
			const newState = {};
			tempService?.fields?.forEach((field) => {
				newState[field.name] =
					defaultCredentials?.[field.name] ||
					(field.type === 'toggle' ? false : '');
			});
			return newState;
		});
	}, [tempService]);

	React.useEffect(() => {
		if (currentPage === 3) {
			updateConnection({
				...connection,
				status: false,
				error: false
			});
			dispatch(setConnection({
				...connection,
				status: false,
				error: false
			}));
		} else {
			setValid(true);
		}
	}, [currentPage]);

	const handleBackPage = () => {
		setClosePopup(true);
	};
	const handlePopup = (action) => {
		if (!action) setClosePopup(false);
	};

	const pages = [
		ConfigureWelcome,
		ConfigureChooseService,
		ConfigureServiceWelcome,
		ConfigureServiceSettings,
		ConfigureServiceVerify,
		ConfigureServiceComplete
	];

	// Next Button Action
	const handleNextPage = () => {
		let proceedNextPage = true;
		if (currentPage === 3) {
			const vl = isValid(credentials, tempService.fields);
			proceedNextPage = vl.isValid;
		}
		if (proceedNextPage) {
			if (currentPage === 3) {
				dispatch(updateTempCredentials(credentials));
			}
			if (pages.length > currentPage + 1) {
				setCurrentPage((prevPage) => {
					return prevPage + 1;
				});
			}
		}
	};
	const handlePrevPage = () => {
		if (currentPage > 0) {
			if (currentPage === 3) {
				setErrors({
					errors: [],
					isValid: true
				});
			}

			setCurrentPage((prevPage) => {
				return prevPage - 1;
			});
		}
	};

	const backToConfigure = () => {
		setCurrentPage(3);
	};

	const handleSave = () => {
		setSaveConfig({
			...saveConfig,
			status: true,
			error: false,
			message: ''
		});
		fetchWP
			.post('serviceSave/', {
				service: tempService,
				credentials,
				settings: settingsDefaultValues?.[tempService.slug]
			})
			.then((response) => {
				setSaveConfig({
					...saveConfig,
					status: false,
					error: false,
					message: response.message
				});
				if (!response?.previousService) {
					dispatch(updateSettings(settingsDefaultValues?.[tempService.slug]));
				}
				dispatch(updateCredentials(credentials));
				dispatch(updateService(tempService));
				history.push({
					pathname: '/'
				});
			})
			.catch((error) => {
				setSaveConfig({
					...saveConfig,
					status: false,
					error: true,
					message: error.message
				});
			});
	};

	return (
		<>
			{closePopup && <CloseConfiguration handlePopup={handlePopup} />}
			<ConfigureHeader onClickBack={handleBackPage} />
			{pages?.map((Page, index) => {
				if (currentPage === index)
					return (
						<div className={style.mainContainer} key={Page}>
							<Page
								index={index}
								configuration={credentials}
								setConfiguration={setCredentials}
								connection={connection}
								updateConnection={updateConnection}
								nextPage={handleNextPage}
								fieldErrors={errors}
								setErrors={setErrors}
							/>
							{currentPage <= 3 ? (
								<ConfigureFooter
									onNext={handleNextPage}
									onPrev={handlePrevPage}
									currentIndex={currentPage}
									logo={logos[tempService?.slug] || false}
									disabled={
										!(errors.isValid && valid) &&
										currentPage === 3
									}
								/>
							) : (
								<ConfigureVerifyFooter
									onNext={handleSave}
									onPrev={backToConfigure}
									connection={connection}
									saveConfig={saveConfig}
								/>
							)}
						</div>
					);
				return null;
			})}
		</>
	);
}

export default Configure;
