import React from 'react';
import style from './style.scss';

import loaderSpinner from '../../images/saveLoader.svg'


export default function SettingsFooter({ save, reset, loader, disabled }) {
	return (
		<div className={style.footerSec}>
			<button type="button" className={style.btnSave} disabled={disabled || loader} onClick={save}>
				{wp.i18n.__('Save Changes', 'offload-media-cloud-storage')}
			</button>
			<button type="button" className={style.btnDefault} onClick={reset} disabled={loader}>
				{wp.i18n.__('Reset Defaults', 'offload-media-cloud-storage')}
			</button>
			{loader ? (
				<div className={style.loader}>
					<img src={loaderSpinner} alt="" />
				</div>
			): ''}
		</div>
	);
}
