import React from 'react';
import style from './style.scss';

export default function ConfigureTextInput({
	label,
	name,
	onChange,
	required,
	value,
	error,
	max='',
	min='',
	pattern='',
	placeholder = '',
	type='text'
}) {
	return (
		<div className={style.inputBox}>
			{label && <label htmlFor={name}>{label}</label>}
			<input
				type={type}
				name={name}
				id={name}
				value={value}
				placeholder={placeholder}
				onChange={onChange}
				required={required}
				pattern={pattern}
				max={max}
				min={min}
				className={error ? style.error : ''}
			/>
		</div>
	);
}
