import React from 'react';
import { NavLink } from 'react-router-dom';
import style from './style.scss';


export default function LicenseHeader() {
	return (
		<div className={style.SettingshHeader}>
			<NavLink exact className={style.NavLink} to="/">
				{wp.i18n.__('Back', 'offload-media-cloud-storage')}
			</NavLink>
		</div>
	);
}
