import React from 'react';
import { useSelector } from 'react-redux';
import style from './style.scss';

import Welcome from '../components/Welcome';

/* Icons */
import icon1 from '../images/icon-get_started.svg';
import icon2 from '../images/icon-settings.svg';
// import icon3 from '../images/icon-license.svg';
import icon4 from '../images/icon-documentation.svg';
import icon5 from '../images/icon-media.svg';
// import icon6 from '../images/icon-balance.svg';
import CardSmall from '../components/CardSmall';
import CardLarge from '../components/CardLarge';
import PremiumBanner from '../components/PremiumBanner';
import { acoofmGetBucketName } from '../helper';


function Dashboard(props) {
	const dashboard = useSelector((state) => state.common.dashboard);
	const configure = useSelector((state) => state.common.configure);
	const { service, credentials } = configure;
	let leftCards = [];

	const rightCards = [
		{
			title: wp.i18n.__("Uploaded Media's", 'offload-media-cloud-storage'),
			count: dashboard.offloaded ? dashboard.offloaded : 0,
			total: false,
			link: '',
			icon: icon5,
			color: '#F0FAF1'
		}
		// {
		// 	title: wp.i18n.__('Media Balance', 'offload-media-cloud-storage'),
		// 	count: dashboard.balance ? dashboard.balance : 0,
		// 	total: dashboard.purchased ? dashboard.purchased : 0,
		// 	link: 'https://acowebs.com',
		// 	icon: icon6,
		// 	color: '#FFF2EC'
		// }
	];

	const defaultLeftCards = [
		// {
		// 	title: wp.i18n.__('License', 'offload-media-cloud-storage'),
		// 	description: wp.i18n.__(
		// 		'Manage your offload media license here',
		// 		'offload-media-cloud-storage'
		// 	),
		// 	icon: icon3,
		// 	color: '#EAF8F1',
		// 	link: '/license',
		// 	disabled: false,
		// 	external: false
		// },
		{
			title: wp.i18n.__('Documentation', 'offload-media-cloud-storage'),
			description: wp.i18n.__(
				'You need any help with configuring the plugin, Visit our documentation page.',
				'offload-media-cloud-storage'
			),
			icon: icon4,
			color: '#F5E7FE',
			link: 'https://acowebs.com/guideline/plugin-docs-faqs/wordpress-offload-media',
			disabled: false,
			external: true
		}
	];
	const getStartedLeftCard = {
		title: wp.i18n.__("Let's Get Started", 'offload-media-cloud-storage'),
		description: wp.i18n.__(
			'Welcome to Offload media! To get started, configure your cloud storage.',
			'offload-media-cloud-storage'
		),
		icon: icon1,
		color: '#FFF0F2',
		link: '/configure',
		disabled: false,
		external: false
	};

	const getStartedConfigureLeftCard = {
		title: wp.i18n.__('Configure', 'offload-media-cloud-storage'),
		description: wp.i18n.__(
			'Change/Modify your cloud storage settings.',
			'offload-media-cloud-storage'
		),
		icon: icon1,
		color: '#FFF0F2',
		link: '/configure',
		service: Object.keys(service).length
			? {
					active: true,
					name: Object.keys(service).length ? service.title : '',
					bucket: acoofmGetBucketName(service, credentials)
			  }
			: false,
		disabled: false,
		external: false
	};

	const settingsLeftCard = {
		title: wp.i18n.__('Settings', 'offload-media-cloud-storage'),
		description: wp.i18n.__(
			'Adjust your service settings to customize your storage read and write operations',
			'offload-media-cloud-storage'
		),
		icon: icon2,
		color: '#EAF8FE',
		link: '/settings',
		disabled: !Object.keys(service).length,
		external: false
	};

	if (Object.keys(service).length === 0) {
		leftCards.push(getStartedLeftCard);
		leftCards.push(settingsLeftCard);
	} else {
		leftCards.push(settingsLeftCard);
		leftCards.push(getStartedConfigureLeftCard);
	}
	leftCards = leftCards.concat(defaultLeftCards);

	return (
		<>
			<Welcome />
			<div className={style.innerPage}>
				<div className={style.left}>
					{leftCards.map((card) => {
						return (
							<CardSmall
								key={card.title}
								title={card.title}
								description={card.description}
								icon={card.icon}
								color={card.color}
								link={card.link}
								service={card?.service ? card?.service : false}
								disabled={card.disabled}
								external={card.external}
							/>
						);
					})}
				</div>
				<div className={style.right}>
					{rightCards.map((card) => {
						return (
							<CardLarge
								key={card.title}
								title={card.title}
								count={card.count}
								total={card.total}
								link={card.link}
								icon={card.icon}
								color={card.color}
							/>
						);
					})}
					{/* <CardLarge
						key="card.title"
						title=""
						count=""
						total=""
						link=""
						icon=""
						color=""
					/> */}
				</div>
			</div>
			<PremiumBanner />
		</>
	);
}

export default Dashboard;
