/* eslint-disable react/no-danger */
import React from 'react';
import style from './style.scss';

import successIcon from '../../images/success.svg';
import errorIcon from '../../images/error.svg';
import warningIcon from '../../images/warning.svg';
import { ClassNames } from '../../helper';


export default function Alert({ type, message, onClose, index }) {
	const [alert, setAlert] = React.useState({});

	const alertList = {
		error: {
			prefix: wp.i18n.__('Error :', 'offload-media-cloud-storage'),
			icon: errorIcon,
			class: style.error
		},
		warning: {
			prefix: wp.i18n.__('Warning :', 'offload-media-cloud-storage'),
			icon: warningIcon,
			class: style.warning
		},
		success: {
			prefix: wp.i18n.__('Success :', 'offload-media-cloud-storage'),
			icon: successIcon,
			class: style.success
		}
	};

	React.useEffect(() => {
		setAlert(alertList?.[type]);
		setTimeout(() => {
			onClose(index);
		}, 5000);
	}, [index]);
	return alert?.prefix ? (
		<div
			className={ClassNames([style.alertContainer, alert?.class])}
			style={{ backgroundColor: alert.color }}
		>
			<div className={style.alertIcon}>
				<img src={alert.icon} alt="" />
			</div>
			<p>
				{alert?.prefix && <span className={style.errorLabel}>{alert?.prefix}</span>}
				<span dangerouslySetInnerHTML={{__html: message}} />
			</p>
			<button
				className={style.closeAlert}
				onClick={()=>onClose(index)}
				type="button"
				aria-label="Close Alert"
			/>
		</div>
	) : (
		''
	);
}
