import React from 'react';

import { ClassNames } from '../../helper';
import style from './style.scss';

export default function TextInput({
	label,
	name,
	handleChangeValues,
	value = '',
	className,
	pattern = '',
	placeholder = '',
	required = false,
	tooltip = false,
	type = 'text',
	lenMin = 0,
	lenMax = 0,
	min = 0,
	max = 0
}) {
	const handleChange = (e) => {
		let valid = true;
		let patternRegex ='';
		if(pattern) {
			patternRegex = new RegExp(pattern);
		}
		if (min && e.target.value < min) {
			valid = false;
		} else if (max && e.target.value > max) {
			valid = false;
		} else if (lenMin && e.target.value.length < lenMin) {
			valid = false;
		} else if (lenMax && e.target.value.length > lenMax) {
			valid = false;
		} else if (pattern && !patternRegex.test(e.target.value)) {
			valid = false;
		}
		if(valid || e.target.value==='') {
			handleChangeValues(e.target.name, e.target.value);
		}
	};
	return (
		<div className={style.inputField}>
			<div className={style.inputLabelOuter}>
				{label && (
					<div className={style.inputOuter}>
						<label className={style.input_label} htmlFor={name}>
							{label}
							{tooltip && (
								<span className={style.tooltip}>
									<span className={style.icon} />
									<div className={style.content}>
										{tooltip}
									</div>
								</span>
							)}
						</label>
					</div>
				)}

				<input
					className={ClassNames([style.textInput, className])}
					type={type}
					name={name}
					placeholder={placeholder}
					required={required}
					value={value}
					onChange={handleChange}
					min={min}
					max={max}
					pattern={pattern}
				/>
			</div>
		</div>
	);
}
