import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import style from './style.scss';

import { ClassNames, fetchWP } from '../../helper';
import MultiStepNavigator from '../../components/MultiStepNavigator';
import { setConnection } from '../../redux/slices/connectionSlice';

import connectingImage from '../../images/connecting-service.svg';
import loading from '../../images/saveLoader.svg';


function ConfigureServiceVerify(props) {
	const {
		connection,
		updateConnection,
		nextPage
	} = props;
	const configure = useSelector((state) => state.tempService);
	const connectionProp = useSelector((state) => state.connection);
	const dispatch = useDispatch();
	const { service, credentials } = configure;

	React.useEffect(() => {
		dispatch(setConnection({
			...connection,
			status: true,
			error: false
		}));
		fetchWP
			.post('serviceConnect/', {
				service,
				credentials
			})
			.then((response) => {
				if (
					parseInt(response.code, 10) >= 200 &&
					parseInt(response.code, 10) < 300
				) {
					updateConnection({
						...connection,
						status: false,
						error: false,
						message: response.message
					});
					dispatch(setConnection({
						...connectionProp,
						status: false,
						error: false,
						message: response.message
					}));
				} else {
					updateConnection({
						...connection,
						status: false,
						error: true,
						message: response.message
					});
					dispatch(setConnection({
						...connectionProp,
						status: false,
						error: true,
						message: response.message
					}));
				}
				nextPage();
			})
			.catch((error) => {
				updateConnection({
					...connection,
					status: false,
					error: true,
					message: (typeof error === 'object'
						? error?.message
						: error
					).replace(/(<([^>]+)>)/gi, '')
				});
				dispatch(setConnection({
					...connectionProp,
					status: false,
					error: true,
					message: (typeof error === 'object'
						? error?.message
						: error
					).replace(/(<([^>]+)>)/gi, '')
				}));
				nextPage();
			});
	}, []);

	return (
		<div className={ClassNames([style.content, style.serviceVerify])}>
			{service.title && (
				<>
					<MultiStepNavigator
						currentStep={3}
						serviceName={service.title}
					/>
					<div className={style.inner}>
						<div className={style.imgSec}>
							<img
								src={connectingImage}
								alt={wp.i18n.__(
									'Offload Media - Cloud Storage',
									'offload-media-cloud-storage'
								)}
							/>
						</div>
						<div className={style.VerifyLoading}>
							<h3>
								{wp.i18n.__(
									`Connecting to ${service.title} server...`,
									'offload-media-cloud-storage'
								)}
							</h3>
							<img src={loading} alt="" />
						</div>
					</div>
				</>
			)}
		</div>
	);
}

export default ConfigureServiceVerify;
