import React, { useEffect, useState } from 'react';
import { HashRouter, Route, Switch } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';

import {
	updateCommonSettings,
	updateLoader
} from './redux/slices/commonSlice';

import style from './backend.scss';

import Loader from './utils/loader';
import { fetchWP } from './helper';
import Page404 from './pages/Page404';
import Dashboard from './pages/Dashboard';
import Header from './components/Header';
import Configure from './pages/Configure';
import PluginSettings from './pages/PluginSettings';
import License from './pages/License';

import { settingsDefaultValues } from './utils/fields';
import { Services } from './utils/variables';

const Settings = () => {
	const dispatch = useDispatch();
	const common = useSelector((state) => state.common);

	const [state, setState] = useState({
		loader: true,
		...common
	});

	useEffect(() => {
		// Fetch common settings on mount
		fetchWP.get('commonSettings/').then((commonSettings) => {
			const { dashboard, configure, settings } = commonSettings;

			let updateData;
			setState((prevState) => {
				const {
					dashboard: defaultDashboard,
					configure: defaultConfigure
				} = prevState;

				const selectedService = Services?.find(
					(ser) => ser.slug === configure?.service?.slug
				);

				updateData = {
					...prevState,
					dashboard: {
						...defaultDashboard,
						...dashboard
					},
					configure: {
						service: {
							...defaultConfigure?.service,
							...selectedService
						},
						credentials: {
							...defaultConfigure?.credentials,
							...configure?.credentials
						}
					},
					settings: {
						...settingsDefaultValues?.[configure?.service?.slug],
						...settings
					}
				};
				return updateData;
			});

			// Update Redux store
			dispatch(updateCommonSettings(updateData));

			// Post updated settings to server
			fetchWP
				.post('updateCommonSettings', {
					configure: updateData.configure,
					settings: updateData.settings
				})
				.then(() => {
					dispatch(updateLoader(false));
					setState((prevState) => ({
						...prevState,
						loader: false
					}));
				});
		});
	}, [dispatch]);

	const { dashboard, loader } = state;

	return (
		<div className={style.innerContent}>
			{loader ? (
				<Loader />
			) : (
				<>
					<Header version={dashboard.version} />
					<HashRouter>
						<div className={style.pageContainer}>
							<Switch>
								<Route
									path="/"
									exact
									render={() => <Dashboard />}
								/>
								<Route
									path="/configure"
									exact
									render={() => <Configure />}
								/>
								<Route
									path="/settings"
									exact
									render={() => <PluginSettings />}
								/>
								<Route
									path="/license"
									exact
									render={() => <License />}
								/>
								<Route render={() => <Page404 />} />
							</Switch>
						</div>
					</HashRouter>
				</>
			)}
		</div>
	);
};

export default Settings;
