import React from 'react';
import style from './style.scss';

import iconClose from '../../images/icon-close.svg';


function ConfirmReset({ onCancel, onSubmit }) {
	return (
		<div className={style.popupOuter}>
			<div className={style.inner}>
				<div className={style.content}>
					<h4>{wp.i18n.__('Reset to defaults ?', 'offload-media-cloud-storage')}</h4>
					<p>
						{wp.i18n.__(
							'Are you sure do you want to reset the current settings to default ?',
							'offload-media-cloud-storage'
						)}
					</p>
					<button type="button" onClick={onCancel}>
						<img src={iconClose} alt="" />
					</button>
				</div>
				<div className={style.footer}>
					<button
						type="button"
						className={style.cancel}
						onClick={onSubmit}
					>
						{wp.i18n.__('Yes', 'offload-media-cloud-storage')}
					</button>
					<button
						type="button"
						className={style.primaryBtn}
						onClick={onCancel}
					>
						{wp.i18n.__('No', 'offload-media-cloud-storage')}
					</button>
				</div>
			</div>
		</div>
	);
}
export default ConfirmReset;
