import React from 'react';
import { ClassNames } from '../../helper';
import style from './style.scss';

import image from '../../images/welcome-image.svg'


export default function ConfigureWelcome() {
	return (
		<div className={ClassNames([style.content, style.welcome])}>
			<div className={style.left}>
				<h2>
					{wp.i18n.__(
						'Welcome to Offload Media',
						'offload-media-cloud-storage'
					)}
				</h2>
				<p>{wp.i18n.__("Thanks for downloading Offload Media!", 'offload-media-cloud-storage')}</p>
				<p>
					{wp.i18n.__(
						"Offload media helps to upload your media to the cloud storage, and it can be served from the server directly.",
						'offload-media-cloud-storage'
					)}
				</p>
				<p>
					{wp.i18n.__(
						"In the following screens, you can set up your service provider's basic configurations that are required to work the plugin. After the configuration, you can adjust the settings exactly as you wanted.",
						'offload-media-cloud-storage'
					)}
				</p>
			</div>
			<div className={style.right}>
				<img src={image} alt="" />
			</div>
		</div>
	);
}
