import React from 'react';
import style from './style.scss';


export default function Page404() {
	return (
		<div>
			<div className={style.container}>
				<h3>
					{wp.i18n.__('404 - Page not found', 'offload-media-cloud-storage')}
				</h3>
				<p>
					{wp.i18n.__(
						'Sorry!! The page you are looking for not found on this settings page',
						'offload-media-cloud-storage'
					)}
				</p>
			</div>
		</div>
	);
}
