import React from 'react';
import style from './style.scss';

export default function ToggleInput({
	label,
	name,
	handleChangeValues,
	checked = false,
	tooltip = false
}) {
	const handleChange = (e) => {
		handleChangeValues(e.target.name, e.target.checked);
	};
	return (
		<div className={style.toggleBox}>
			<div className={style.toggle}>
				{label && (
					<div className={style.labelOuter}>
						<label className={style.toggle_label} htmlFor={name}>
							{label}
							{tooltip && (
								<span className={style.tooltip}>
									<span className={style.icon} />
									<div className={style.content}>
										{tooltip}
									</div>
								</span>
							)}
						</label>
					</div>
				)}

				<label htmlFor={name}>
					<input
						className={style.toggle_checkbox}
						type="checkbox"
						name={name}
						id={name}
						checked={checked}
						onChange={handleChange}
					/>

					<div className={style.toggle_switch} />
				</label>
			</div>
		</div>
	);
}
