import FetchWP from '../utils/fetchWP';

export const ClassNames = (classes) => classes.join(' ');
export function htmlEntities(str) {
	const plainText = str.replace(/<[^>]*>?/gm, '');
	return plainText;
}

/**
 * validate email
 */
export const validateEmail = (email) => {
	const re = /^\w+([.-]?\w+)*@\w+([.-]?\w+)*(\.\w{2,3})+$/;
	return re.test(String(email).toLowerCase());
};

// Worpress API Init
export const fetchWP = new FetchWP({
	restURL: window.acoofm_object.root,
	restNonce: window.acoofm_object.api_nonce
});

/**
 * Convert RGBA color value to Hex
 * @param {Object} rgba
 * @returns {String}
 */
export function RGBAToHexA(rgba) {
	const hexa = Object.keys(rgba).map((key) => {
		const val = rgba[key];
		let color =
			key === 'a' ? Math.round(val * 255).toString(16) : val.toString(16);
		if (color.length === 1) color = `0${color}`;
		return color;
	});
	hexa.unshift('#');
	return hexa.join('');
}

/**
 * To set menu active
 *
 */
export const setCurrentMenu = (path) => {
	const menuLis = document.querySelectorAll(
		'#toplevel_page_acoofm-admin-ui ul li'
	);
	menuLis.forEach((li) => {
		li.classList.remove('current');

		if (
			li.querySelector('a')?.getAttribute('href') ===
			`admin.php?page=acoofm-admin-ui#/${path}`
		) {
			// using getAttribute as href not returing relative value
			li.classList.add('current');
		}
	});
};

export function acoofmGetBucketName(service, credentials) {
	if (Object.keys(service).length) {
		switch (service.slug) {
			case 's3':
				return credentials?.bucket_name;
			case 'google':
				return credentials?.google_bucket_name;
			case 'ocean':
				return credentials?.ocean_bucket_name;
			case 'r2':
				return credentials?.r2_bucket_name;
			default:
				return '';
		}
	} else {
		return '';
	}
}
