import React from 'react';
import Tooltip from '../Tooltip';
import style from './style.scss';

export default function ConfigureToggleInput({
	label,
	name,
	onChange,
	tooltip = '',
	value = false
}) {
	return (
		<div className={style.toggleBox}>
			<div className={style.toggle} htmlFor={name}>
				<label htmlFor={name}>
					<input
						className={style.toggle_checkbox}
						type="checkbox"
						id={name}
						checked={value}
						name={name}
						onChange={onChange}
					/>
					<div className={style.toggle_switch} />
					{label && (
						<span className={style.toggle_label}>{label}</span>
					)}
				</label>
				{tooltip && <Tooltip content={tooltip} />}
			</div>
		</div>
	);
}
