import React from 'react';
import style from './style.scss';
import PluginLogo from '../../images/logo.svg';


export default function ConfigureFooter({
	onNext,
	onPrev,
	currentIndex,
	disabled,
	logo = false
}) {
	return (
		<div className={style.footer}>
			<div className={style.imgSec}>
				<div className={style.logoSec}>
					<img src={PluginLogo} alt="" />
				</div>
				{logo && (
					<div className={style.logo}>
						<img src={logo} alt="" />
					</div>
				)}
			</div>
			<div className={style.btnSec}>
				{!(currentIndex === 0 || currentIndex === 1) && (
					<button
						onClick={onPrev}
						type="button"
						className={style.btnBack}
					>
						{wp.i18n.__('Back', 'offload-media-cloud-storage')}
					</button>
				)}
				<button
					onClick={onNext}
					type="button"
					className={style.btnNext}
					disabled={disabled}
				>
					{wp.i18n.__('Next', 'offload-media-cloud-storage')}
				</button>
			</div>
		</div>
	);
}
