import React from 'react';
import style from './style.scss';


export default function LicenseFooter() {
	return (
		<div className={style.footerSec}>
			<button type="button" className={style.btnSave}>
				{wp.i18n.__('Save Changes', 'offload-media-cloud-storage')}
			</button>
            <button type="button" className={style.btnDefault}>
				{wp.i18n.__('Reset Defaults', 'offload-media-cloud-storage')}
			</button>
		</div>
	);
}
